<?php
declare(strict_types=1);
session_start();
require dirname(__DIR__).'/config/config.php';
require_sign_in();
if (($_SESSION['role'] ?? '') !== 'headteacher') { http_response_code(403); exit('Only the Head of School can manage classes, streams and subjects.'); }
$uid=(int)$_SESSION['user_id'];$db=db();$error='';$saved=isset($_GET['saved']);$activeSubjectClassId=(int)($_GET['show_subjects']??0);$activeStreamClassId=(int)($_GET['stream_class']??0);$openAddClass=isset($_GET['add_class']);$openAddStream=isset($_GET['show_stream']);
$q=$db->prepare('SELECT s.id,s.name FROM schools s JOIN school_memberships m ON m.school_id=s.id WHERE m.user_id=? ORDER BY s.name');$q->execute([$uid]);$schools=$q->fetchAll();$schoolIds=array_map('intval',array_column($schools,'id'));
$actions=['add_class','edit_class','delete_class','add_stream','edit_stream','delete_stream','add_subject','edit_subject','delete_subject'];
if($_SERVER['REQUEST_METHOD']==='POST'){
    verify_csrf();$action=(string)($_POST['action']??'');$schoolId=(int)($_POST['school_id']??0);$name=trim((string)($_POST['name']??''));$activeSubjectClassId=in_array($action,['add_subject','edit_subject','delete_subject'],true)?(int)($_POST['class_id']??$_POST['return_class_id']??0):0;$activeStreamClassId=$action==='add_stream'?(int)($_POST['class_id']??0):0;$openAddClass=$action==='add_class';$openAddStream=$action==='add_stream';
    if(!in_array($schoolId,$schoolIds,true)){$error='Choose a school assigned to your account.';}
    elseif(!in_array($action,$actions,true)){$error='Choose a valid school setup action.';}
    elseif(!in_array($action,['delete_class','delete_stream','delete_subject'],true)&&($name===''||strlen($name)>(in_array($action,['add_subject','edit_subject'],true)?100:80))){$error='Enter a name within the allowed length.';}
    else{
        try{
            $db->beginTransaction();$recordId=(int)($_POST['record_id']??0);$entity='';$auditAction='create';$details=['school_id'=>$schoolId];
            if($action==='add_class'){$q=$db->prepare('INSERT INTO school_classes(school_id,name,created_by) VALUES(?,?,?)');$q->execute([$schoolId,$name,$uid]);$recordId=(int)$db->lastInsertId();$entity='school_class';$details['name']=$name;}
            elseif($action==='edit_class'){$q=$db->prepare('SELECT name FROM school_classes WHERE id=? AND school_id=?');$q->execute([$recordId,$schoolId]);$old=$q->fetch();if(!$old)throw new DomainException('That class is not part of your school.');$q=$db->prepare('UPDATE school_classes SET name=? WHERE id=? AND school_id=?');$q->execute([$name,$recordId,$schoolId]);foreach(['pupils','teacher_assignments','pupil_results','learning_notes','result_delegations'] as $table){$q=$db->prepare("UPDATE $table SET class_level=? WHERE school_id=? AND class_level=?");$q->execute([$name,$schoolId,$old['name']]);}$entity='school_class';$auditAction='update';$details+=['previous_name'=>$old['name'],'name'=>$name];}
            elseif($action==='delete_class'){$q=$db->prepare('SELECT name FROM school_classes WHERE id=? AND school_id=?');$q->execute([$recordId,$schoolId]);$old=$q->fetch();if(!$old)throw new DomainException('That class is not part of your school.');foreach(['pupils','teacher_assignments','pupil_results','learning_notes','result_delegations'] as $table){$q=$db->prepare("SELECT COUNT(*) FROM $table WHERE school_id=? AND class_level=?");$q->execute([$schoolId,$old['name']]);if((int)$q->fetchColumn()>0)throw new DomainException('This class has current school records. Move or remove those records before deleting the class.');}$q=$db->prepare('DELETE FROM school_classes WHERE id=? AND school_id=?');$q->execute([$recordId,$schoolId]);$entity='school_class';$auditAction='delete';$details['name']=$old['name'];}
            elseif($action==='add_stream'){$classId=(int)($_POST['class_id']??0);$q=$db->prepare('SELECT id,name FROM school_classes WHERE id=? AND school_id=?');$q->execute([$classId,$schoolId]);if(!$q->fetch())throw new DomainException('Choose a class in the selected school.');$q=$db->prepare('INSERT INTO school_streams(class_id,name,created_by) VALUES(?,?,?)');$q->execute([$classId,$name,$uid]);$recordId=(int)$db->lastInsertId();$entity='school_stream';$details+=['class_id'=>$classId,'name'=>$name];}
            elseif($action==='edit_stream'||$action==='delete_stream'){$q=$db->prepare('SELECT st.name,c.id class_id,c.name class_name FROM school_streams st JOIN school_classes c ON c.id=st.class_id WHERE st.id=? AND c.school_id=?');$q->execute([$recordId,$schoolId]);$old=$q->fetch();if(!$old)throw new DomainException('That stream is not part of your school.');if($action==='edit_stream'){$q=$db->prepare('UPDATE school_streams SET name=? WHERE id=?');$q->execute([$name,$recordId]);foreach(['pupils','pupil_results'] as $table){$q=$db->prepare("UPDATE $table SET stream=? WHERE school_id=? AND class_level=? AND stream=?");$q->execute([$name,$schoolId,$old['class_name'],$old['name']]);}$auditAction='update';$details+=['class_id'=>(int)$old['class_id'],'previous_name'=>$old['name'],'name'=>$name];}else{foreach(['pupils','pupil_results'] as $table){$q=$db->prepare("SELECT COUNT(*) FROM $table WHERE school_id=? AND class_level=? AND stream=?");$q->execute([$schoolId,$old['class_name'],$old['name']]);if((int)$q->fetchColumn()>0)throw new DomainException('This stream is used by current pupil or result records and cannot be deleted.');}$q=$db->prepare('DELETE FROM school_streams WHERE id=?');$q->execute([$recordId]);$auditAction='delete';$details+=['class_id'=>(int)$old['class_id'],'name'=>$old['name']];}$entity='school_stream';}
            else{$classId=(int)($_POST['class_id']??$_POST['return_class_id']??0);$q=$db->prepare('SELECT c.id,c.name FROM school_classes c JOIN school_memberships m ON m.school_id=c.school_id WHERE c.id=? AND c.school_id=? AND m.user_id=?');$q->execute([$classId,$schoolId,$uid]);$class=$q->fetch();if(!$class)throw new DomainException('Choose a class in the selected school.');if($action==='add_subject'){$q=$db->prepare('INSERT INTO school_class_subjects(class_id,name,created_by) VALUES(?,?,?)');$q->execute([$classId,$name,$uid]);$recordId=(int)$db->lastInsertId();$details+=['class_id'=>$classId,'class_name'=>$class['name'],'name'=>$name];}else{$q=$db->prepare('SELECT name FROM school_class_subjects WHERE id=? AND class_id=?');$q->execute([$recordId,$classId]);$old=$q->fetch();if(!$old)throw new DomainException('That subject does not belong to this class.');if($action==='edit_subject'){$q=$db->prepare('UPDATE school_class_subjects SET name=? WHERE id=? AND class_id=?');$q->execute([$name,$recordId,$classId]);foreach(['teacher_assignments','pupil_results','learning_notes'] as $table){$q=$db->prepare("UPDATE $table SET subject=? WHERE school_id=? AND class_level=? AND subject=?");$q->execute([$name,$schoolId,$class['name'],$old['name']]);}$auditAction='update';$details+=['class_id'=>$classId,'previous_name'=>$old['name'],'name'=>$name];}else{foreach(['teacher_assignments','pupil_results','learning_notes'] as $table){$q=$db->prepare("SELECT COUNT(*) FROM $table WHERE school_id=? AND class_level=? AND subject=?");$q->execute([$schoolId,$class['name'],$old['name']]);if((int)$q->fetchColumn()>0)throw new DomainException('This subject is used by current teaching, result or note records and cannot be deleted.');}$q=$db->prepare('DELETE FROM school_class_subjects WHERE id=? AND class_id=?');$q->execute([$recordId,$classId]);$auditAction='delete';$details+=['class_id'=>$classId,'name'=>$old['name']];}}$entity='school_subject';$activeSubjectClassId=$classId;}
            $q=$db->prepare('INSERT INTO audit_logs(actor_id,action,entity_type,entity_id,details) VALUES(?,?,?,?,?)');$q->execute([$uid,$auditAction,$entity,$recordId,json_encode($details,JSON_THROW_ON_ERROR)]);$db->commit();$redirect='school_setup.php?saved=1';if(in_array($action,['add_subject','edit_subject','delete_subject'],true))$redirect.='&show_subjects='.$activeSubjectClassId;header('Location: '.$redirect);exit;
        }catch(DomainException $ex){if($db->inTransaction())$db->rollBack();$error=$ex->getMessage();}catch(PDOException $ex){if($db->inTransaction())$db->rollBack();$error=$ex->getCode()==='23000'?'That name already exists in this class or school.':'School setup could not be saved. Check the database migration and try again.';}catch(Throwable $ex){if($db->inTransaction())$db->rollBack();$error='School setup could not be saved. Check the database migration and try again.';}
    }
}
$classes=[];$streamsByClass=[];$subjectsByClass=[];$loadError='';
try{if($schoolIds){$marks=implode(',',array_fill(0,count($schoolIds),'?'));$q=$db->prepare("SELECT c.id,c.school_id,c.name,s.name school_name FROM school_classes c JOIN schools s ON s.id=c.school_id WHERE c.school_id IN ($marks) ORDER BY s.name,c.name");$q->execute($schoolIds);$classes=$q->fetchAll();$classIds=array_map('intval',array_column($classes,'id'));if($classIds){$classMarks=implode(',',array_fill(0,count($classIds),'?'));$q=$db->prepare("SELECT st.id,st.class_id,st.name FROM school_streams st WHERE st.class_id IN ($classMarks) ORDER BY st.name");$q->execute($classIds);foreach($q->fetchAll() as $row)$streamsByClass[(int)$row['class_id']][]=$row;$q=$db->prepare("SELECT sj.id,sj.class_id,sj.name FROM school_class_subjects sj WHERE sj.class_id IN ($classMarks) ORDER BY sj.name");$q->execute($classIds);foreach($q->fetchAll() as $row)$subjectsByClass[(int)$row['class_id']][]=$row;}}}catch(Throwable $ex){$loadError='School setup could not be loaded. Apply the latest database migration.';}
