"hidden" name="school_id" value="<?=$class['school_id']?>"><button class="button danger" type="submit">Delete stream</button></form></div></details><?php endforeach;endif;?></div><button type="button" class="text-action" data-open-stream="<?=$class['id']?>">Add stream</button></td><td><div class="class-row-actions"><details class="row-actions setup-row-actions"><summary class="button">Edit</summary><form method="post" class="setup-edit-form"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="edit_class"><input type="hidden" name="record_id" value="<?=$class['id']?>"><input type="hidden" name="school_id" value="<?=$class['school_id']?>"><label class="sr-only" for="class-<?=$class['id']?>">Class name</label><input id="class-<?=$class['id']?>" name="name" value="<?=e($class['name'])?>" maxlength="80" required><button class="button primary" type="submit">Save</button></form></details><button type="button" class="button" data-show-subjects="<?=$class['id']?>" aria-haspopup="dialog">Show subjects <span class="subject-count"><?=count($classSubjects)?></span></button><form method="post" onsubmit="return confirm('Delete this class and its streams and subjects? This is only possible when no active academic records depend on it.')"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="delete_class"><input type="hidden" name="record_id" value="<?=$class['id']?>"><input type="hidden" name="school_id" value="<?=$class['school_id']?>"><button type="submit" class="button danger">Delete</button></form></div></td></tr><?php endforeach;?></tbody></table></div><?php endif;?></section>
<?php foreach($classes as $class):$classSubjects=$subjectsByClass[(int)$class['id']]??[];?><dialog class="subject-dialog" id="subjects-<?=$class['id']?>" aria-labelledby="subject-dialog-title-<?=$class['id']?>"><div class="subject-dialog-head"><div><div class="eyebrow">CLASS SUBJECTS</div><h2 id="subject-dialog-title-<?=$class['id']?>"><?=e($class['name'])?></h2><p class="muted"><?=e($class['school_name'])?> · <?=count($classSubjects)?> subjects</p></div><button type="button" class="icon-button" data-close-dialog aria-label="Close subjects dialog">×</button></div><div class="subject-dialog-body"><?php if($error&&$activeSubjectClassId===(int)$class['id']):?><div class="notice error" role="alert"><?=e($error)?></div><?php endif;?><h3>Subjects for this class</h3><?php if(!$classSubjects):?><div class="subject-empty">No subjects have been added to this class.</div><?php else:?><div class="subject-edit-list"><?php foreach($classSubjects as $subject):?><form method="post" class="subject-edit-form"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="edit_subject"><input type="hidden" name="record_id" value="<?=$subject['id']?>"><input type="hidden" name="school_id" value="<?=$class['school_id']?>"><input type="hidden" name="class_id" value="<?=$class['id']?>"><label class="sr-only" for="subject-<?=$subject['id']?>">Edit subject name</label><input id="subject-<?=$subject['id']?>" name="name" value="<?=e($subject['name'])?>" maxlength="100" required><button type="submit" class="button primary">Save</button><button type="submit" name="action" value="delete_subject" class="button danger" formnovalidate onclick="return confirm('Delete this subject?')">Delete</button></form><?php endforeach;?></div><?php endif;?><form method="post" class="subject-add-form"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="add_subject"><input type="hidden" name="school_id" value="<?=$class['school_id']?>"><input type="hidden" name="class_id" value="<?=$class['id']?>"><label for="new-subject-<?=$class['id']?>">Add a subject</label><div class="subject-add-row"><input id="new-subject-<?=$class['id']?>" name="name" maxlength="100" required placeholder="For example, Mathematics"><button type="submit" class="button primary">Add subject</button></div></form></div><div class="subject-dialog-foot"><button type="button" class="button" data-close-dialog>Done</button></div></dialog><?php endforeach;?>
