<dialog class="setup-dialog" id="add-class-dialog" aria-labelledby="add-class-title"><form method="post" class="setup-dialog-form"><div class="subject-dialog-head"><div><div class="eyebrow">SCHOOL STRUCTURE</div><h2 id="add-class-title">Add a class</h2><p class="muted">Give the class a name, then add streams and subjects.</p></div><button type="button" class="icon-button" data-close-dialog aria-label="Close dialog">×</button></div><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="add_class"><?php if($error&&$openAddClass):?><div class="notice error" role="alert"><?=e($error)?></div><?php endif;?><div class="setup-dialog-fields"><?=render_school_select('add-class-school',$schools)?><div><label for="new-class-name">Class name</label><input id="new-class-name" name="name" maxlength="80" required value="<?=($openAddClass)?e($_POST['name']??''):''?>" placeholder="For example, Grade 4"></div></div><div class="subject-dialog-foot"><button type="button" class="button" data-close-dialog>Cancel</button><button type="submit" class="button primary">Add class</button></div></form></dialog>
<dialog class="setup-dialog" id="add-stream-dialog" aria-labelledby="add-stream-title"><form method="post" class="setup-dialog-form"><div class="subject-dialog-head"><div><div class="eyebrow">CLASS STREAMS</div><h2 id="add-stream-title">Add a stream</h2><p class="muted">Add a stream inside a class, for example Maroon or Red.</p></div><button type="button" class="icon-button" data-close-dialog aria-label="Close dialog">×</button></div><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="add_stream"><div class="setup-dialog-fields"><?=render_school_select('add-stream-school',$schools)?><div><label for="add-stream-class">Class</label><select id="add-stream-class" name="class_id" required><option value="">Choose class</option><?php foreach($classes as $class):?><option value="<?=$class['id']?>" data-school-id="<?=$class['school_id']?>" <?=$activeStreamClassId===(int)$class['id']?'selected':''?>><?=e($class['name'].' · '.$class['school_name'])?></option><?php endforeach;?></select></div><div><label for="new-stream-name">Stream name</label><input id="new-stream-name" name="name" maxlength="80" required value="<?=($openAddStream)?e($_POST['name']??''):''?>" placeholder="For example, Maroon"></div></div><div class="subject-dialog-foot"><button type="button" class="button" data-close-dialog>Cancel</button><button type="submit" class="button primary" <?=!$classes?'disabled':''?>>Add stream</button></div></form></dialog>
<script>
document.querySelectorAll('[data-show-subjects]').forEach(button=>button.addEventListener('click',()=>document.querySelector('#subjects-'+button.dataset.showSubjects)?.showModal()));
document.querySelectorAll('[data-close-dialog]').forEach(button=>button.addEventListener('click',()=>button.closest('dialog')?.close()));document.querySelectorAll('dialog').forEach(dialog=>dialog.addEventListener('click',event=>{if(event.target===dialog)dialog.close()}));
document.querySelector('[data-open-add-class]')?.addEventListener('click',()=>document.querySelector('#add-class-dialog')?.showModal());document.querySelectorAll('[data-open-stream]').forEach(button=>button.addEventListener('click',()=>{const dialog=document.querySelector('#add-stream-dialog');const classSelect=dialog?.querySelector('#add-stream-class');if(classSelect){classSelect.value=button.dataset.openStream;const schoolId=classSelect.selectedOptions[0]?.dataset.schoolId;const school=dialog.querySelector('[name="school_id"]');if(school)school.value=schoolId||'';school?.dispatchEvent(new Event('change'))}dialog?.showModal()}));
const streamDialog=document.querySelector('#add-stream-dialog'),schoolSelect=streamDialog?.querySelector('[name="school_id"]'),classSelect=streamDialog?.querySelector('#add-stream-class');function filterStreamClasses(){if(!schoolSelect||!classSelect)return;const schoolId=schoolSelect.value;[...classSelect.options].forEach(option=>{if(!option.value)return;const visible=!schoolId||option.dataset.schoolId===schoolId;option.hidden=!visible;option.disabled=!visible;if(!visible&&option.selected)classSelect.value=''})}schoolSelect?.addEventListener('change',filterStreamClasses);filterStreamClasses();
<?php if($activeSubjectClassId):?>document.querySelector('#subjects-<?=$activeSubjectClassId?>')?.showModal();<?php endif;?><?php if($openAddClass):?>document.querySelector('#add-class-dialog')?.showModal();<?php endif;?><?php if($openAddStream):?>document.querySelector('#add-stream-dialog')?.showModal();<?php endif;?>
</script></body></html>
